    35→// WriteCommitted writes a committed checkpoint to the entire/sessions branch.
    36→// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
    37→//
    38→// For task checkpoints (IsTask=true), additional files are written under tasks/<tool-use-id>/:
    39→//   - For incremental checkpoints: checkpoints/NNN-<tool-use-id>.json
    40→//   - For final checkpoints: checkpoint.json and agent-<agent-id>.jsonl
    41→func (s *GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
    42→	// Validate identifiers to prevent path traversal and malformed data
    43→	if opts.CheckpointID.IsEmpty() {
    44→		return errors.New("invalid checkpoint options: checkpoint ID is required")
    45→	}
    46→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
    47→		return fmt.Errorf("invalid checkpoint options: %w", err)
    48→	}
    49→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
    50→		return fmt.Errorf("invalid checkpoint options: %w", err)
    51→	}
    52→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
    53→		return fmt.Errorf("invalid checkpoint options: %w", err)
    54→	}
    55→
    56→	// Ensure sessions branch exists
    57→	if err := s.ensureSessionsBranch(); err != nil {
    58→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
    59→	}
    60→
    61→	// Get current branch tip and flatten tree
    62→	ref, entries, err := s.getSessionsBranchEntries()
    63→	if err != nil {
    64→		return err
    65→	}
    66→
    67→	// Use sharded path: <id[:2]>/<id[2:]>/
    68→	basePath := opts.CheckpointID.Path() + "/"
    69→
    70→	// Track task metadata path for commit trailer
    71→	var taskMetadataPath string
    72→
    73→	// Handle task checkpoints
    74→	if opts.IsTask && opts.ToolUseID != "" {
    75→		taskMetadataPath, err = s.writeTaskCheckpointEntries(ctx, opts, basePath, entries)
    76→		if err != nil {
    77→			return err
    78→		}
    79→	}
    80→
    81→	// Write standard checkpoint entries (transcript, prompts, context, metadata)
    82→	if err := s.writeStandardCheckpointEntries(ctx, opts, basePath, entries); err != nil {
    83→		return err
    84→	}
    85→
    86→	// Build and commit
    87→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
    88→	if err != nil {
    89→		return err
    90→	}
    91→
    92→	commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
    93→	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, opts.AuthorName, opts.AuthorEmail)
    94→	if err != nil {
    95→		return err
    96→	}
    97→
    98→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
    99→	newRef := plumbing.NewHashReference(refName, newCommitHash)
   100→	if err := s.repo.Storer.SetReference(newRef); err != nil {
   101→		return fmt.Errorf("failed to set branch reference: %w", err)
   102→	}
   103→
   104→	return nil
   105→}
