   107→// getSessionsBranchEntries returns the sessions branch reference and flattened tree entries.
   108→func (s *GitStore) getSessionsBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
   109→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   110→	ref, err := s.repo.Reference(refName, true)
   111→	if err != nil {
   112→		return nil, nil, fmt.Errorf("failed to get sessions branch reference: %w", err)
   113→	}
   114→
   115→	parentCommit, err := s.repo.CommitObject(ref.Hash())
   116→	if err != nil {
   117→		return nil, nil, fmt.Errorf("failed to get commit object: %w", err)
   118→	}
   119→
   120→	baseTree, err := parentCommit.Tree()
   121→	if err != nil {
   122→		return nil, nil, fmt.Errorf("failed to get commit tree: %w", err)
   123→	}
