   125→	entries := make(map[string]object.TreeEntry)
   126→	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
   127→		return nil, nil, err
   128→	}
   129→
   130→	return ref, entries, nil
   131→}
