   220→// writeStandardCheckpointEntries writes session files to numbered subdirectories and
   221→// maintains a CheckpointSummary at the root level with aggregated statistics.
   222→//
   223→// Structure:
   224→//
   225→//	basePath/
   226→//	├── metadata.json         # CheckpointSummary (aggregated stats)
   227→//	├── 1/                    # First session
   228→//	│   ├── metadata.json     # CommittedMetadata (session-specific, includes initial_attribution)
   229→//	│   ├── full.jsonl
   230→//	│   ├── prompt.txt
   231→//	│   ├── context.md
   232→//	│   └── content_hash.txt
   233→//	├── 2/                    # Second session
   234→//	└── ...
   235→func (s *GitStore) writeStandardCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   236→	// Read existing summary to get current session count
   237→	var existingSummary *CheckpointSummary
   238→	metadataPath := basePath + paths.MetadataFileName
   239→	if entry, exists := entries[metadataPath]; exists {
   240→		existing, err := s.readSummaryFromBlob(entry.Hash)
   241→		if err == nil {
   242→			existingSummary = existing
   243→		}
   244→	}
   245→
   246→	// Determine session index (0, 1, 2, ...) - 0-based numbering
   247→	sessionIndex := 0
   248→	if existingSummary != nil {
   249→		sessionIndex = len(existingSummary.Sessions)
   250→	}
   251→
   252→	// Write session files to numbered subdirectory
   253→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
   254→	sessionFilePaths, err := s.writeSessionToSubdirectory(ctx, opts, sessionPath, entries)
   255→	if err != nil {
   256→		return err
   257→	}
   258→
   259→	// Copy additional metadata files from directory if specified (to session subdirectory)
   260→	if opts.MetadataDir != "" {
   261→		if err := s.copyMetadataDir(ctx, opts.MetadataDir, sessionPath, entries); err != nil {
   262→			return fmt.Errorf("failed to copy metadata directory: %w", err)
   263→		}
   264→	}
   265→
   266→	// Update root metadata.json with CheckpointSummary
   267→	return s.writeCheckpointSummary(opts, basePath, entries, existingSummary, sessionFilePaths)
   268→}
