   270→// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
   271→// Returns the absolute file paths from the git tree root for the sessions map.
   272→// Prompts and context are filtered through the configured output filter.
   273→func (s *GitStore) writeSessionToSubdirectory(ctx context.Context, opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
   274→	filePaths := SessionFilePaths{}
   275→
   276→	// Write transcript (filtering is done inside writeTranscript)
   277→	if err := s.writeTranscript(ctx, opts, sessionPath, entries); err != nil {
   278→		return filePaths, err
