   281→	filePaths.ContentHash = "/" + sessionPath + paths.ContentHashFileName
   282→
   283→	// Write prompts (filtered)
   284→	if len(opts.Prompts) > 0 {
   285→		promptContent := strings.Join(opts.Prompts, "\n\n---\n\n")
   286→		filteredPrompt, err := filter.Content(ctx, []byte(promptContent), paths.PromptFileName)
   287→		if err != nil {
   288→			return filePaths, fmt.Errorf("failed to filter prompts: %w", err)
   289→		}
   290→		blobHash, err := CreateBlobFromContent(s.repo, filteredPrompt)
   291→		if err != nil {
   292→			return filePaths, err
