   304→		filteredContext, err := filter.Content(ctx, opts.Context, paths.ContextFileName)
   305→		if err != nil {
   306→			return filePaths, fmt.Errorf("failed to filter context: %w", err)
   307→		}
   308→		blobHash, err := CreateBlobFromContent(s.repo, filteredContext)
   309→		if err != nil {
   310→			return filePaths, err
