   356→// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
   357→func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingSummary *CheckpointSummary, sessionFilePaths SessionFilePaths) error {
   358→	summary := CheckpointSummary{
   359→		CheckpointID:     opts.CheckpointID,
   360→		Strategy:         opts.Strategy,
   361→		Branch:           opts.Branch,
   362→		CheckpointsCount: opts.CheckpointsCount,
   363→		FilesTouched:     opts.FilesTouched,
   364→		Sessions:         []SessionFilePaths{sessionFilePaths},
   365→		TokenUsage:       opts.TokenUsage,
   366→	}
   367→
   368→	// Aggregate with existing summary if present
   369→	if existingSummary != nil {
   370→		summary.CheckpointsCount = existingSummary.CheckpointsCount + opts.CheckpointsCount
   371→		summary.FilesTouched = mergeFilesTouched(existingSummary.FilesTouched, opts.FilesTouched)
   372→		summary.TokenUsage = aggregateTokenUsage(existingSummary.TokenUsage, opts.TokenUsage)
   373→
   374→		// Copy existing sessions and append new session
   375→		summary.Sessions = make([]SessionFilePaths, len(existingSummary.Sessions)+1)
   376→		copy(summary.Sessions, existingSummary.Sessions)
   377→		summary.Sessions[len(existingSummary.Sessions)] = sessionFilePaths
   378→	}
   379→
   380→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
   381→	if err != nil {
   382→		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
   383→	}
   384→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   385→	if err != nil {
   386→		return err
   387→	}
   388→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
   389→		Name: basePath + paths.MetadataFileName,
   390→		Mode: filemode.Regular,
   391→		Hash: metadataHash,
   392→	}
   393→	return nil
   394→}
