   396→// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
   397→func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
   398→	blob, err := repo.BlobObject(hash)
   399→	if err != nil {
   400→		return nil, fmt.Errorf("failed to get blob: %w", err)
   401→	}
   402→
   403→	reader, err := blob.Reader()
   404→	if err != nil {
   405→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
   406→	}
   407→	defer reader.Close()
   408→
   409→	var result T
   410→	if err := json.NewDecoder(reader).Decode(&result); err != nil {
   411→		return nil, fmt.Errorf("failed to decode: %w", err)
   412→	}
   413→
   414→	return &result, nil
   415→}
