   422→// aggregateTokenUsage sums two TokenUsage structs.
   423→// Returns nil if both inputs are nil.
   424→func aggregateTokenUsage(a, b *agent.TokenUsage) *agent.TokenUsage {
   425→	if a == nil && b == nil {
   426→		return nil
   427→	}
   428→	result := &agent.TokenUsage{}
   429→	if a != nil {
   430→		result.InputTokens = a.InputTokens
   431→		result.CacheCreationTokens = a.CacheCreationTokens
   432→		result.CacheReadTokens = a.CacheReadTokens
   433→		result.OutputTokens = a.OutputTokens
   434→		result.APICallCount = a.APICallCount
   435→	}
   436→	if b != nil {
   437→		result.InputTokens += b.InputTokens
   438→		result.CacheCreationTokens += b.CacheCreationTokens
   439→		result.CacheReadTokens += b.CacheReadTokens
   440→		result.OutputTokens += b.OutputTokens
   441→		result.APICallCount += b.APICallCount
   442→	}
   443→	return result
   444→}
