   530→// buildCommitMessage constructs the commit message with proper trailers.
   531→// The commit subject is always "Checkpoint: <id>" for consistency.
   532→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
   533→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
   534→	var commitMsg strings.Builder
   535→
   536→	// Subject line is always the checkpoint ID for consistent formatting
   537→	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))
   538→
   539→	// Include custom description in body if provided (e.g., task checkpoint details)
   540→	if opts.CommitSubject != "" {
   541→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
   542→	}
   543→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
   544→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
   545→	if opts.Agent != "" {
   546→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
   547→	}
   548→	if opts.EphemeralBranch != "" {
   549→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch))
   550→	}
   551→	if taskMetadataPath != "" {
   552→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath))
   553→	}
   554→
   555→	return commitMsg.String()
   556→}
