   700→// ReadSessionContentByID reads a session's content by its session ID.
   701→// This is useful when you have the session ID but don't know its index within the checkpoint.
   702→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   703→// Returns an error if no session with the given ID exists in the checkpoint.
   704→func (s *GitStore) ReadSessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string) (*SessionContent, error) {
   705→	summary, err := s.ReadCommitted(ctx, checkpointID)
   706→	if err != nil {
   707→		return nil, err
   708→	}
   709→	if summary == nil {
   710→		return nil, ErrCheckpointNotFound
   711→	}
   712→
   713→	// Iterate through sessions to find the one with matching session ID
   714→	for i := range len(summary.Sessions) {
   715→		content, readErr := s.ReadSessionContent(ctx, checkpointID, i)
   716→		if readErr != nil {
   717→			continue
   718→		}
   719→		if content != nil && content.Metadata.SessionID == sessionID {
   720→			return content, nil
   721→		}
   722→	}
   723→
   724→	return nil, fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID)
   725→}
