  1003→// CreateBlobFromContent creates a blob object from in-memory content.
  1004→// Exported for use by strategy package (session_test.go)
  1005→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
  1006→	obj := repo.Storer.NewEncodedObject()
  1007→	obj.SetType(plumbing.BlobObject)
  1008→	obj.SetSize(int64(len(content)))
  1009→
  1010→	writer, err := obj.Writer()
  1011→	if err != nil {
  1012→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
  1013→	}
  1014→
  1015→	_, err = writer.Write(content)
  1016→	if err != nil {
  1017→		_ = writer.Close()
  1018→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
  1019→	}
  1020→	if err := writer.Close(); err != nil {
  1021→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
  1022→	}
  1023→
  1024→	hash, err := repo.Storer.SetEncodedObject(obj)
  1025→	if err != nil {
  1026→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
  1027→	}
  1028→	return hash, nil
  1029→}
