  1031→// shouldFilterFile returns true if the file should be filtered through the output filter.
  1032→// Files containing potentially sensitive user content are filtered.
  1033→func shouldFilterFile(filename string) bool {
  1034→	base := filepath.Base(filename)
  1035→	// Filter transcripts, prompts, context, and agent transcripts
  1036→	switch base {
  1037→	case paths.TranscriptFileName, paths.PromptFileName, paths.ContextFileName:
  1038→		return true
  1039→	}
  1040→	// Filter agent-*.jsonl files (subagent transcripts)
  1041→	if strings.HasPrefix(base, "agent-") && strings.HasSuffix(base, ".jsonl") {
  1042→		return true
  1043→	}
  1044→	return false
  1045→}
