  1047→// copyMetadataDir copies all files from a directory to the checkpoint path.
  1048→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
  1049→// Files containing potentially sensitive content are filtered through the configured output filter.
  1050→func (s *GitStore) copyMetadataDir(ctx context.Context, metadataDir, basePath string, entries map[string]object.TreeEntry) error {
  1051→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
  1052→		if err != nil {
  1053→			return err
  1054→		}
  1055→		if info.IsDir() {
  1056→			return nil
  1057→		}
  1058→
  1059→		// Skip symlinks to prevent reading files outside the metadata directory.
  1060→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
  1061→		// then be captured in the checkpoint and stored in git history.
  1062→		if info.Mode()&os.ModeSymlink != 0 {
  1063→			return nil
  1064→		}
  1065→
  1066→		// Get relative path within metadata dir
  1067→		relPath, err := filepath.Rel(metadataDir, path)
  1068→		if err != nil {
  1069→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
  1070→		}
  1071→
  1072→		// Prevent path traversal via symlinks pointing outside the metadata dir
  1073→		if strings.HasPrefix(relPath, "..") {
  1074→			return fmt.Errorf("path traversal detected: %s", relPath)
  1075→		}
  1076→
  1077→		// Read file content
  1078→		content, err := os.ReadFile(path) //nolint:gosec // path comes from walking trusted metadata directory
  1079→		if err != nil {
  1080→			return fmt.Errorf("failed to read file %s: %w", path, err)
  1081→		}
