  1139→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1140→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1141→// The agentType is used for reassembling chunks in the correct format.
  1142→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1143→	// Collect all transcript-related files
  1144→	var chunkFiles []string
  1145→	var hasBaseFile bool
  1146→
  1147→	for _, entry := range tree.Entries {
  1148→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1149→			hasBaseFile = true
  1150→		}
  1151→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1152→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1153→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1154→			if idx > 0 {
  1155→				chunkFiles = append(chunkFiles, entry.Name)
  1156→			}
  1157→		}
  1158→	}
  1159→
  1160→	// If we have chunk files, read and reassemble them
  1161→	if len(chunkFiles) > 0 {
  1162→		// Sort chunk files by index
  1163→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1164→
  1165→		// Check if base file should be included as chunk 0.
  1166→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1167→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1168→		if hasBaseFile {
  1169→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1170→		}
  1171→
  1172→		var chunks [][]byte
  1173→		for _, chunkFile := range chunkFiles {
  1174→			file, err := tree.File(chunkFile)
  1175→			if err != nil {
  1176→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1177→					slog.String("chunk_file", chunkFile),
  1178→					slog.String("error", err.Error()),
  1179→				)
  1180→				continue
  1181→			}
  1182→			content, err := file.Contents()
  1183→			if err != nil {
  1184→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1185→					slog.String("chunk_file", chunkFile),
  1186→					slog.String("error", err.Error()),
  1187→				)
  1188→				continue
  1189→			}
  1190→			chunks = append(chunks, []byte(content))
  1191→		}
  1192→
  1193→		if len(chunks) > 0 {
  1194→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1195→			if err != nil {
  1196→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1197→			}
  1198→			return result, nil
  1199→		}
  1200→	}
  1201→
  1202→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1203→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1204→		if content, err := file.Contents(); err == nil {
  1205→			return []byte(content), nil
  1206→		}
  1207→	}
  1208→
  1209→	// Try legacy filename
  1210→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1211→		if content, err := file.Contents(); err == nil {
  1212→			return []byte(content), nil
  1213→		}
  1214→	}
  1215→
  1216→	return nil, nil
  1217→}
