  1238→	metadataPath := checkpointID.Path() + "/" + paths.MetadataFileName
  1239→
  1240→	// Walk commit history looking for the commit that introduced this file
  1241→	iter, err := s.repo.Log(&git.LogOptions{
  1242→		From:  ref.Hash(),
  1243→		Order: git.LogOrderCommitterTime,
  1244→	})
  1245→	if err != nil {
  1246→		return Author{}, nil
  1247→	}
  1248→	defer iter.Close()
  1249→
  1250→	var author Author
  1251→	var foundCommit *object.Commit
  1252→
  1253→	err = iter.ForEach(func(c *object.Commit) error {
  1254→		tree, treeErr := c.Tree()
  1255→		if treeErr != nil {
  1256→			return nil //nolint:nilerr // Skip commits we can't read, continue searching
  1257→		}
  1258→
  1259→		_, fileErr := tree.File(metadataPath)
  1260→		if fileErr != nil {
  1261→			// File doesn't exist in this commit - we've gone past the creation point
  1262→			if foundCommit != nil {
  1263→				return errStopIteration
  1264→			}
  1265→			return nil
  1266→		}
  1267→
  1268→		// File exists - track it (oldest one with file is the creator)
  1269→		foundCommit = c
  1270→		author = Author{
  1271→			Name:  c.Author.Name,
  1272→			Email: c.Author.Email,
  1273→		}
  1274→		return nil
  1275→	})
  1276→
  1277→	// Ignore errStopIteration - it's just for early exit
  1278→	if err != nil && !errors.Is(err, errStopIteration) {
  1279→		return Author{}, nil
  1280→	}
  1281→
  1282→	return author, nil
  1283→}
